--
-- Table structure for table `development`
--

DROP TABLE IF EXISTS `development`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `development` (
  `development_id` int NOT NULL AUTO_INCREMENT,
  `project_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `developer_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `area_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`development_id`),
  UNIQUE KEY `uq_development` (`project_name`,`area_name`),
  KEY `fk_development_location` (`area_name`),
  KEY `idx_development_developer` (`developer_name`),
  CONSTRAINT `fk_development_developer` FOREIGN KEY (`developer_name`) REFERENCES `developer` (`developer_name`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_development_location` FOREIGN KEY (`area_name`) REFERENCES `location` (`area_name`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4552 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

