--
-- Table structure for table `property`
--

DROP TABLE IF EXISTS `property`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `property` (
  `listing_ref` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `listing_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `area_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `development_id` int DEFAULT NULL,
  `area_sqm` decimal(10,2) DEFAULT NULL,
  `bedrooms` tinyint unsigned DEFAULT NULL,
  `bathrooms` tinyint unsigned DEFAULT NULL,
  `floor` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `finishing` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `completion_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `garden_roof_sqm` decimal(10,2) DEFAULT NULL,
  `installments_left_years` tinyint unsigned DEFAULT NULL,
  `payment_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `contract_year` smallint DEFAULT NULL,
  `delivery_year` smallint DEFAULT NULL,
  `down_payment` decimal(15,2) DEFAULT NULL,
  `remaining_amount` decimal(15,2) DEFAULT NULL,
  `installment_amount` decimal(15,2) DEFAULT NULL,
  `installment_freq` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `market_price` decimal(15,2) DEFAULT NULL,
  `commission_pct` decimal(5,2) DEFAULT NULL,
  `gain_amount` decimal(15,2) DEFAULT NULL,
  `is_negotiable` tinyint(1) NOT NULL DEFAULT '0',
  `docs_verified` tinyint(1) NOT NULL DEFAULT '0',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `scraped_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`listing_ref`),
  KEY `idx_property_area_type` (`area_name`,`type`),
  KEY `idx_property_development` (`development_id`),
  KEY `idx_property_contract` (`contract_year`),
  CONSTRAINT `fk_property_development` FOREIGN KEY (`development_id`) REFERENCES `development` (`development_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_property_location` FOREIGN KEY (`area_name`) REFERENCES `location` (`area_name`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_property_amounts` CHECK ((((`down_payment` is null) or (`down_payment` >= 0)) and ((`installment_amount` is null) or (`installment_amount` >= 0)) and ((`market_price` is null) or (`market_price` >= 0)))),
  CONSTRAINT `chk_property_area` CHECK (((`area_sqm` is null) or (`area_sqm` > 0))),
  CONSTRAINT `chk_property_commis` CHECK (((`commission_pct` is null) or (`commission_pct` between 0 and 100))),
  CONSTRAINT `chk_property_contract` CHECK (((`contract_year` is null) or (`contract_year` between 1990 and 2100))),
  CONSTRAINT `chk_property_delivery` CHECK (((`delivery_year` is null) or (`delivery_year` between 1990 and 2100))),
  CONSTRAINT `chk_property_garden` CHECK (((`garden_roof_sqm` is null) or (`garden_roof_sqm` > 0)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
